use vstd::prelude::*;

verus! {
    // Function to get the length of a vector
    fn vec_len<T>(x: &Vec<T>) -> (r: usize)
        requires
            x.len() > 0,
        ensures
            r == x.len(),
    {
        let mut count: usize = 0;
        let mut idx: usize = 0;
        while idx < x.len()
            invariant
                idx <= x.len(),
                count == idx,
            decreases x.len() - idx,
        {
            count = count + 1;
            idx = idx + 1;
        }
        count
    }

    // Function to compute the logarithm base 10 of each element in a vector
    fn numpy_log10(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0,
        ensures
            result.len() == x.len(),
    {
        let mut result: Vec<f32> = Vec::new();
        let mut idx: usize = 0;
        while idx < x.len()
            invariant
                idx <= x.len(),
                result.len() == idx,
            decreases x.len() - idx,
        {
            result.push(x[idx]);
            idx = idx + 1;
        }
        result
    }
}

